args<-commandArgs(trailingOnly=TRUE);O<-if(length(args)) args[1] else 'review_response/source_filter_integrated_working_v5_2026-10-28'
I<-file.path(O,'source_filter_inputs');D<-file.path(O,'source_filter_statistics');F<-file.path(O,'figures');dir.create(F,showWarnings=FALSE,recursive=TRUE)
suppressPackageStartupMessages({library(ggplot2);library(patchwork)})
x<-as.matrix(read.csv(file.path(I,'Counts_268_original_codes.csv'),row.names=1,check.names=FALSE));a<-as.matrix(read.csv(file.path(I,'Counts_41_original_codes.csv'),row.names=1,check.names=FALSE));b<-as.matrix(read.csv(file.path(I,'Counts_39_original_codes.csv'),row.names=1,check.names=FALSE));m<-read.csv(file.path(I,'Metadata_original_codes.csv'))
stopifnot(identical(colnames(x),m$SourceCode),all(x[rownames(a),]==a),all(a[rownames(b),]==b))
p<-sweep(x,2,colSums(x),'/');rules<-read.csv(file.path(D,'Table_S2C_3_threshold_counts.csv'))
for(i in seq_len(nrow(rules))){r<-rules[i,];ids<-m$SourceCode[m$Location==r$Location&m$Fraction==r$Fraction];n<-sum(rowSums(p[,ids,drop=FALSE]>=r$minimum_relative_abundance)>=r$minimum_libraries);stopifnot(n==r$n_taxa_passing,length(ids)==r$n_group_libraries)}
q<-read.csv(file.path(D,'Filtering_library_disposition.csv'));stopifnot(identical(q$SourceCode,colnames(x)),max(abs(q$discarded_268_to_41_pct-100*(1-colSums(a)/colSums(x))))<1e-10,max(abs(q$discarded_41_to_39_pct-100*(1-colSums(b)/colSums(a))))<1e-10)
writeLines('PASS: independent R reconstruction agrees with all 48 site/fraction/rule counts and all 298 per-library discarded-count percentages. No contamination probability, validation, hypothesis test or source-mixture estimate is calculated.',file.path(D,'Independent_R_source_filter_verification.txt'))
rules$Location<-factor(rules$Location,levels=c('VAGINA','CERVIX','ENDOMETRIUM'),labels=c('Vagina','Cervix','Endometrium'));rules$Fraction<-factor(rules$Fraction,levels=c('PRE','IgA','IgM','IgG'));rules$rule<-factor(rules$rule,levels=c('0.5% in 2 libraries','0.5% in 3 libraries','0.5% in 4 libraries','10% in 2 libraries'))
theme_set(theme_bw(base_size=11)+theme(panel.grid.minor=element_blank(),legend.position='bottom',strip.background=element_rect(fill='grey94'),plot.title=element_text(face='bold')))
pa<-ggplot(rules,aes(Fraction,n_taxa_passing,fill=rule))+geom_col(position=position_dodge(width=.85),width=.8)+facet_wrap(~Location,nrow=1)+scale_fill_manual(values=c('#245D88','#5795BF','#AACBDD','#DE8F42'))+labs(title='A  Assignment counts meeting each analytical selection rule',x='Retained library fraction',y='Exported assignments meeting rule',fill=NULL)+scale_y_continuous(expand=expansion(mult=c(0,.08)))
long<-rbind(transform(q,stage='268 to 41: denominator is 268-assignment export',discarded_pct=discarded_268_to_41_pct),transform(q,stage='41 to 39: denominator is the 41-assignment set',discarded_pct=discarded_41_to_39_pct));long$Location<-factor(long$Location,levels=c('VAGINA','CERVIX','ENDOMETRIUM'),labels=c('Vagina','Cervix','Endometrium'));long$stage<-factor(long$stage,levels=unique(long$stage))
pb<-ggplot(long,aes(Location,discarded_pct))+geom_boxplot(outlier.shape=NA,width=.5,fill='white',colour='grey45')+geom_point(aes(colour=Location),position=position_jitter(width=.13,height=0,seed=20261028),size=1.1,alpha=.65)+facet_wrap(~stage,nrow=1)+scale_colour_manual(values=c('#327AAA','#52A46B','#CF7559'),guide='none')+scale_y_continuous(limits=c(0,100),breaks=seq(0,100,25),expand=expansion(mult=c(.015,.03)))+labs(title='B  Per-library fraction of assignment counts discarded',x=NULL,y='Discarded assignment counts (%)')
fig<-pa/pb+plot_layout(heights=c(1,1.05))+plot_annotation(caption='Descriptive reconstruction of 149 libraries from 15 women; points are libraries, not independent women.\nExported-assignment counts are not all raw sequencing reads. Selection does not establish contaminant status.',theme=theme(plot.caption=element_text(size=9,hjust=0)))
ggsave(file.path(F,'FigureS14_filtering_reconstruction.png'),fig,width=11,height=8,dpi=200,bg='white');ggsave(file.path(F,'FigureS14_filtering_reconstruction.pdf'),fig,width=11,height=8)
write.csv(long,file.path(D,'FigureS14_disposition_plotted_values.csv'),row.names=FALSE);capture.output(sessionInfo(),file=file.path(F,'Source_filter_R_sessionInfo.txt'))
cat('Independent checks passed; one revised source-filtering figure rendered.\n')
